@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(PosUsuario)
    private readonly usuarioRepository: Repository<PosUsuario>,
    private jwtService: JwtService
  ) {}

  async login(dto: LoginDto) {
    const usuario = await this.usuarioRepository.findOne({
      where: {
        nombreUsuario: dto.user,
        contrasenaHash: dto.password,
      },
    });

    if (!usuario || !usuario.activo) {
      throw new UnauthorizedException('Usuario o contraseña incorrectos');
    }

    const payload = { username: usuario.nombreUsuario, sub: usuario.idUsuario, perfil: usuario.rol === 'Administrador' ? 1 : (usuario.rol === 'Soporte' ? 3 : 2) };

    return {
      success: true,
      access_token: this.jwtService.sign(payload),
      idUsuario: usuario.idUsuario,
      usuario: usuario.nombreUsuario,
      nombreCompleto: usuario.nombreCompleto,
      idPerfil: usuario.rol === 'Administrador' ? 1 : (usuario.rol === 'Soporte' ? 3 : 2),
      permisos: usuario.permisos || [],
      app: 1,
    };
  }

  }

    idPerfil: usuario.rol === 'Administrador' ? 1 : (usuario.rol === 'Soporte' ? 3 : 2),
    permisos: usuario.permisos || [],
    app: 1,
  };
}

}

import { createParamDecorator, ExecutionContext } from '@nestjs/common';

/**
 * Decorator para extraer el usuario autenticado desde el JWT token.
 * Uso: @CurrentUser() user: { idUsuario, usuario, rol, idSucursal, idEmpresa }
 */
export const CurrentUser = createParamDecorator(
  (data: string | undefined, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    const user = request.user;
    return data ? user?.[data] : user;
  },
);

import { ExecutionContext, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { AuthGuard } from '@nestjs/passport';
import { IS_PUBLIC_KEY } from './public.decorator';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) {
    super();
  }

  canActivate(context: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }
    return super.canActivate(context);
  }
}

import { ExtractJwt, Strategy } from 'passport-jwt';
import { PassportStrategy } from '@nestjs/passport';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private configService: ConfigService) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: (() => {
        const secret = configService.get<string>('JWT_SECRET');
        if (!secret) throw new Error('JWT_SECRET is required');
        return secret;
      })(),
    });
  }

  async validate(payload: any) {
    return { 
      idUsuario: payload.sub, 
      usuario: payload.username, 
      rol: payload.rol, 
      idSucursal: payload.sucursal,
      idEmpresa: payload.idEmpresa
    };
  }
}

import { SetMetadata } from '@nestjs/common';

export const IS_PUBLIC_KEY = 'isPublic';
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);

import { Injectable, CanActivate, ExecutionContext, ForbiddenException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

export const ROLES_KEY = 'roles';
export const Roles = (...roles: string[]) => 
  (target: any, key?: any, descriptor?: any) => {
    Reflect.defineMetadata(ROLES_KEY, roles, descriptor ? descriptor.value : target);
    return descriptor ?? target;
  };

/**
 * Guard que verifica que el usuario tenga uno de los roles requeridos.
 * Uso: @Roles('Administrador', 'Soporte') en el controlador.
 */
@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();
    if (!user) return false;

    const hasRole = requiredRoles.includes(user.rol);
    if (!hasRole) {
      throw new ForbiddenException(`Acceso denegado. Se requiere uno de los siguientes roles: ${requiredRoles.join(', ')}`);
    }

    return true;
  }
}

    return true;
  }
}

