          const ivaCalc = aplicaIva ? (baseIva * (ivaRate / 100)) : 0;
          pCompra.precioVenta = baseIva + ivaCalc;
        }
      }

    pCompra.stockActual = Number(pCompra.stockActual) + Number(item.cantidad);
    await queryRunner.manager.save(PosProducto, pCompra);

